{"summary": "Implement max_sum_rectangular_grid with 8-direction adjacency via column-max house robber DP.", "files": {"solution.py": """"Write a function to find out the maximum sum such that no two chosen numbers are adjacent for the given rectangular grid of dimension 2 x n."""


def max_sum_rectangular_grid(grid, n):
    """Return the maximum sum such that no two chosen numbers are adjacent.

    Adjacent means sharing an edge or a corner (horizontally, vertically or
    diagonally). For a 2 x n grid this means at most one cell can be chosen
    from any two consecutive columns, so each column contributes
    max(grid[0][i], grid[1][i]) and the problem reduces to 1-D house-robber.
    Empty selection is allowed, so the result is at least 0.
    """
    try:
        if n <= 0:
            return 0
    except TypeError:
        return 0
    try:
        row0 = grid[0]
        row1 = grid[1]
    except (TypeError, IndexError, KeyError):
        return 0
    try:
        m = min(n, len(row0), len(row1))
    except TypeError:
        return 0
    if m <= 0:
        return 0
    incl = row0[0] if row0[0] > row1[0] else row1[0]
    excl = 0
    for i in range(1, m):
        curr = row0[i] if row0[i] > row1[i] else row1[i]
        new_excl = incl if incl > excl else excl
        incl = excl + curr
        excl = new_excl
    result = incl if incl > excl else excl
    return result if result > 0 else 0
